# Source descriptors preserve periods as printed instead of inventing a committee date.
sources=[dict(file=A,title='Internal Audit Plan Update Report (End of March 2025), Appendix A',date=None,period_end='2025-03-31',pages=2,what_it_is='Completed-work appendix, not full audit reports; hidden extraction text also says Appendix B.'),dict(file=Q,title='Internal Audit Plan Update Report (End of December 2025), Appendix A',date=None,period_end='2025-12-31',pages=1,what_it_is='Completed-work appendix, not full audit reports.'),dict(file=P,title='Internal Audit Plan 2025-2028',date='2025-04-29',pages=7,what_it_is='Governance Committee covering report only; appendices A–F not included.'),dict(file=S,title='Risk Management Strategy / Risk Management Strategy 2024-27',date='2024-12-12',pages=35,what_it_is='Governance covering report and Appendix A strategy, including risk policy and definitions.')]
opinion_basis=[item(src,1,span(src,1,'The overall opinion is derived','2) COMPLETED FOLLOW UPS'),section='NOTE below completed-audits table',id='BASIS-'+str(i)) for i,src in enumerate([A,Q],1)]
