discrepancies=[
 strategy(14,'Negligible (1), Minor (2), Medium (2), Major (4), or Critical impact(5):',id='DISC-01',section='4.3 vs Table 1',description='Prose labels Medium (2); Table 1 labels Medium 3. Both recorded; table entries used as structured scale.'),
 strategy(14,'0.25% - 1% annual WBC budget £500k £2M',id='DISC-02',section='Table 1',description='Major GBP cell lacks a range separator; budget percentages overlap with Medium 0.1%–0.3%. GBP bands and budget shares are preserved separately without resolving the overlap.'),
 strategy(14,'Less than 0.01% annual WBC budget £17.5k',id='DISC-03',section='Table 1',description='Negligible financial cell prints £17.5k without a GBP inequality; upper figure recorded with boundary ambiguity rather than guessing a strictness.'),
 strategy(21,'Score 9 or above',id='DISC-04',section='Figure 4 vs Table 4 on p.19',description='Figure 4 says Corporate Risk Register includes scores 9 or above; Table 4 directs adding Extreme scores 15–25. Preserve both and disclose which response table is used.'),
 strategy(19,'Medium - High (Amber) 8-12',id='DISC-05',section='Table 4 vs Figure 1 p.18',description='Figure 1 uses High for scores 8–12 whereas Table 4 calls the band Medium - High. Numeric boundaries agree for all attainable products.'),
 item(A,1,'Internal Audit Plan Update Report Appendix A Appendix B',id='DISC-06',section='header',description='Text extraction includes Appendix B in the completed-work header; visible rendered document title is Appendix A. Do not infer another included appendix.')]
